        switch (rop) {
            case 0x005A0049:
                // GDI_PATINVERT: D = P ^ D
                this.cctx.globalCompositeOperation = 'xor';
                return true;
                break;
            case 0x00F00021:
                // GDI_PATCOPY: D = P
                this.cctx.globalCompositeOperation = 'copy';
                return true;
                break;
            case 0x00CC0020:
                // GDI_SRCCOPY: D = S
                this.cctx.globalCompositeOperation = 'source-over';
                return true;
                break;
